def expand_blocks(grid):
    rows, cols = len(grid), len(grid[0])
    output = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val in [2, 0, 1, 3, 4, 6, 8]:  # Background or noise
                # Check if we should expand 5 or 9 into this cell
